Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/i915: Unlink NV12 planes earlier
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

unlink_nv12_plane() will clobber parts of the plane state
potentially already set up by plane_atomic_check(), so we
must make sure not to call the two in the wrong order.
The problem happens when a plane previously selected as
a Y plane is now configured as a normal plane by user space.
plane_atomic_check() will first compute the proper plane
state based on the userspace request, and unlink_nv12_plane()
later clears some of the state.

This used to work on account of unlink_nv12_plane() skipping
the state clearing based on the plane visibility. But I removed
that check, thinking it was an impossible situation. Now when
that situation happens unlink_nv12_plane() will just WARN
and proceed to clobber the state.

Rather than reverting to the old way of doing things, I think
it's more clear if we unlink the NV12 planes before we even
compute the new plane state.

Cc: stable@vger.kernel.org
Reported-by: Khaled Almahallawy <khaled.almahallawy@intel.com>
Closes: https://lore.kernel.org/intel-gfx/20260212004852.1920270-1-khaled.almahallawy@intel.com/
Tested-by: Khaled Almahallawy <khaled.almahallawy@intel.com>
Fixes: 6a01df2f1b2a ("drm/i915: Remove pointless visible check in unlink_nv12_plane()")
Signed-off-by: Ville Syrjälä <ville.syrjala@linux.intel.com>
Link: https://patch.msgid.link/20260316163953.12905-2-ville.syrjala@linux.intel.com
Reviewed-by: Uma Shankar <uma.shankar@intel.com>
(cherry picked from commit 017ecd04985573eeeb0745fa2c23896fb22ee0cc)
Signed-off-by: Joonas Lahtinen <joonas.lahtinen@linux.intel.com>

Here is the root cause:
The bug was caused by an ordering issue where `unlink_nv12_plane()` was called after `plane_atomic_check()` had already configured plane state. Originally, `unlink_nv12_plane()` had a visibility check that prevented state clearing in certain cases, but that check was removed in commit `6a01df2f1b2a`, exposing the ordering problem. When a plane previously used as a Y plane is reconfigured as a normal plane, `plane_atomic_check()` sets correct state, then `unlink_nv12_plane()` clears parts of that state, leading to incorrect plane configuration and a WARN.

Here is the patch:
 }

+static void unlink_nv12_plane(struct intel_crtc_state *crtc_state,
+			      struct intel_plane_state *plane_state);
+
 void intel_plane_set_invisible(struct intel_crtc_state *crtc_state,
 			       struct intel_plane_state *plane_state)
 {
 	struct intel_plane *plane = to_intel_plane(plane_state->uapi.plane);

+	unlink_nv12_plane(crtc_state, plane_state);
+
 	crtc_state->active_planes &= ~BIT(plane->id);
 	crtc_state->scaled_planes &= ~BIT(plane->id);
 	crtc_state->nv12_planes &= ~BIT(plane->id);
 	crtc_state->c8_planes &= ~BIT(plane->id);
 	crtc_state->async_flip_planes &= ~BIT(plane->id);
 	crtc_state->data_rate[plane->id] = 0;
 	crtc_state->data_rate_y[plane->id] = 0;
 	crtc_state->rel_data_rate[plane->id] = 0;
 	crtc_state->rel_data_rate_y[plane->id] = 0;
 	crtc_state->plane_min_cdclk[plane->id] = 0;

 	plane_state->uapi.visible = false;
 }


 static void unlink_nv12_plane(struct intel_crtc_state *crtc_state,
 			      struct intel_plane_state *plane_state)
 {
 	struct intel_display *display = to_intel_display(plane_state);
 	struct intel_plane *plane = to_intel_plane(plane_state->uapi.plane);

+	if (!plane_state->planar_linked_plane)
+		return;
+
 	plane_state->planar_linked_plane = NULL;

 	if (!plane_state->is_y_plane)
 		return;

 	drm_WARN_ON(display->drm, plane_state->uapi.visible);

 	plane_state->is_y_plane = false;

 	crtc_state->enabled_planes &= ~BIT(plane->id);
 	crtc_state->active_planes &= ~BIT(plane->id);
 	crtc_state->update_planes |= BIT(plane->id);
 	crtc_state->data_rate[plane->id] = 0;
 	crtc_state->rel_data_rate[plane->id] = 0;
 }

 static int icl_check_nv12_planes(struct intel_atomic_state *state,
 				 struct intel_crtc *crtc)
 {
 	struct intel_display *display = to_intel_display(state);
 	struct intel_crtc_state *crtc_state =
 		intel_atomic_get_new_crtc_state(state, crtc);
 	struct intel_plane_state *plane_state;
 	struct intel_plane *plane;
 	int i;

 	if (DISPLAY_VER(display) < 11)
 		return 0;

 	/*
 	 * Destroy all old plane links and make the Y plane invisible
 	 * in the crtc_state->active_planes mask.
 	 */
 	for_each_new_intel_plane_in_state(state, plane, plane_state, i) {
 		if (plane->pipe != crtc->pipe)
 			continue;

-		if (plane_state->planar_linked_plane)
-			unlink_nv12_plane(crtc_state, plane_state);
+		unlink_nv12_plane(crtc_state, plane_state);
 	}

 	if (!crtc_state->nv12_planes)
 		return 0;

 	for_each_new_intel_plane_in_state(state, plane, plane_state, i) {
 		struct intel_plane_state *y_plane_state = NULL;
 		struct intel_plane *y_plane;

 		if (plane->pipe != crtc->pipe)
 			continue;

 		if ((crtc_state->nv12_planes & BIT(plane->id)) == 0)
 			continue;

 		for_each_intel_plane_on_crtc(display->drm, crtc, y_plane) {
 			if (!icl_is_nv12_y_plane(display, y_plane->id))
 				continue;

 			if (crtc_state->active_planes & BIT(y_plane->id))
 				continue;

 			y_plane_state = intel_atomic_get_plane_state(state, y_plane);
 			if (IS_ERR(y_plane_state))
 				return PTR_ERR(y_plane_state);

 			break;
 		}

 		if (!y_plane_state) {
 			drm_dbg_kms(display->drm,
 				    "[CRTC:%d:%s] need %d free Y planes for planar YUV\n",
 				    crtc->base.base.id, crtc->base.name,
 				    hweight8(crtc_state->nv12_planes));
 			return -EINVAL;
 		}

 		link_nv12_planes(crtc_state, plane_state, y_plane_state);
 	}

 	return 0;
 }



